 IEnumerator PhysicalAim(GridShiftWorldAction action){var mesh=action.focusOwner.GetComponentsInChildren<MeshRenderer>().Where(r=>r.GetComponent<TMP_Text>()==null).OrderByDescending(r=>r.bounds.size.x*r.bounds.size.z).First();for(int i=0;i<16;i++){var at=action.transform.position+Quaternion.Euler(0,i*22.5f,0)*Vector3.forward*.8f;at.y=GridShiftApartment.Instance.transform.position.y+.19f;Place(at);yield return null;var delta=Vector3.ProjectOnPlane(mesh.bounds.center-player.CameraTransform.position,Vector3.up);if(delta.sqrMagnitude>.01f)player.transform.rotation=Quaternion.LookRotation(delta);player.CameraTransform.LookAt(mesh.bounds.center);yield return new WaitForSeconds(.2f);if(InteractionFocus.Selected(action,player.transform)&&action.Reachable(player)){Check(GridShiftContextHUD.Visible,"mirar diretamente na malha da banheira oferece a rotina sem mirar ponto lateral");Capture("mirar-banheira");yield break;}}Check(false,"mira no objeto físico deve selecionar banho");} IEnumerator CoveredCitizen(){var source=Object.FindObjectsByType<GridShiftCitizen>(FindObjectsSortMode.None).First(c=>c.GetComponentInChildren<Animator>()?.isHuman==true);var victim=Object.Instantiate(source.gameObject);victim.name="Covered pedestrian test fixture";var agent=victim.GetComponent<PedestrianAgent>();if(agent!=null){agent.ExternalControl=true;agent.enabled=false;}var van=DeliveryManager.Instance.GetComponent<GridShiftActiveOperations>().Van;var body=van.GetComponent<Rigidbody>();var original=body.position;var groundAt=original+Vector3.right*6;Check(Physics.Raycast(groundAt+Vector3.up*3,Vector3.down,out var floor,6,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore),"piso para regressão de pedestre coberto");groundAt.y=floor.point.y+.05f;victim.transform.position=groundAt;Physics.SyncTransforms();yield return null;var citizen=victim.GetComponent<GridShiftCitizen>();Check(citizen.Strike(Vector3.forward*2.5f),"pedestre real entra em ragdoll");yield return new WaitForSeconds(1);var hips=victim.GetComponentInChildren<Animator>().GetBoneTransform(HumanBodyBones.Hips);body.position=new Vector3(hips.position.x,groundAt.y,hips.position.z);body.linearVelocity=Vector3.zero;Physics.SyncTransforms();yield return new WaitForSeconds(6.5f);Check(victim.GetComponentsInChildren<CharacterJoint>().Length>0,"pedestre coberto por van continua físico e não se levanta no teto");body.position=original;body.linearVelocity=Vector3.zero;Physics.SyncTransforms();float limit=Time.time+10;while(victim.GetComponentsInChildren<CharacterJoint>().Length>0&&Time.time<limit)yield return null;Check(victim.GetComponentsInChildren<CharacterJoint>().Length==0&&Mathf.Abs(victim.transform.position.y-floor.point.y)<.25f,"pedestre se levanta no chão após liberar espaço");Object.Destroy(victim);}
 IEnumerator RoadCheck(GridShiftPlayerVan van){Check(van.GetComponentsInChildren<SphereCollider>().Count(c=>c.name=="Rounded wheel road contact")==4,"quatro contatos arredondados no carro");
  Check(GridShiftRoadSurface22.Corrected>0,"marcas decorativas sem colisão preservam asfalto");
  // Static real city geometry; suspend moving actors only for this controlled road traversal.
  foreach(var car in Object.FindObjectsByType<TrafficCar>(FindObjectsSortMode.None))car.gameObject.SetActive(false);foreach(var ped in Object.FindObjectsByType<PedestrianAgent>(FindObjectsSortMode.None))ped.gameObject.SetActive(false);
  var road=Object.FindObjectsByType<MeshCollider>(FindObjectsSortMode.None).Where(c=>c.name.StartsWith("Road Intersection_01")).OrderBy(c=>(c.bounds.center-van.transform.position).sqrMagnitude).First();var start=road.bounds.center+new Vector3(3,0,-15);Check(Physics.Raycast(start+Vector3.up*3,Vector3.down,out var floor,6,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore),"pista real sob ponto inicial");start.y=floor.point.y+.04f;var rb=van.GetComponent<Rigidbody>();rb.position=start;rb.rotation=Quaternion.identity;rb.linearVelocity=rb.angularVelocity=Vector3.zero;Physics.SyncTransforms();yield return new WaitForSeconds(.8f);Place(van.EntryPosition+Vector3.left*.7f+Vector3.up*.08f);Check(van.Enter(player),"entrada real para teste de faixa: "+van.LastError);van.ScriptedInput=true;van.SetInput(1,0,false);float high=rb.position.y,low=high,vertical=0,condition=van.Health.condition;var begin=rb.position;for(int i=0;i<260;i++){yield return new WaitForFixedUpdate();high=Mathf.Max(high,rb.position.y);low=Mathf.Min(low,rb.position.y);vertical=Mathf.Max(vertical,Mathf.Abs(rb.linearVelocity.y));if(rb.position.z-begin.z>34)break;}van.SetInput(0,0,true);for(int i=0;i<150&&van.Speed>.25f;i++)yield return new WaitForFixedUpdate();float distance=Vector3.ProjectOnPlane(rb.position-begin,Vector3.up).magnitude;log.AppendLine("MEASURE real crossing distance="+distance+" heightVariation="+(high-low)+" maxVerticalSpeed="+vertical+" obstacle="+van.LastObstacle);Write();Check(distance>28,"carro atravessa faixa e emendas reais sem travar");Check(high-low<.15f,"travessia mantém variação vertical abaixo de 15 cm");Check(van.Health.condition>=condition-.1f,"travessia não causa dano invisível");Check(van.Exit(),"frear e sair continuam funcionais");van.ScriptedInput=false;player.BlockControls(false);
 }
 void Capture(string name){Directory.CreateDirectory(DirectoryName);var source=Camera.main;if(source==null)source=Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.isActiveAndEnabled);var overlays=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var target=new RenderTexture(1920,1080,24);var prior=source.targetTexture;var active=RenderTexture.active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=source;c.planeDistance=.8f;}source.targetTexture=target;Canvas.ForceUpdateCanvases();source.Render();RenderTexture.active=target;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(Path.Combine(DirectoryName,name+".png"),image.EncodeToPNG());source.targetTexture=prior;RenderTexture.active=active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}target.Release();Object.Destroy(target);Object.Destroy(image);}
